    cancel_active_operations(state).await
}
async fn cancel_active_operations(state: &AppState) -> Option<String> {
    let generation = state.0.turn_generation.fetch_add(1, Ordering::AcqRel) + 1;
    state.0.audio.lock().await.clear();
