        self.assertEqual(speaker().clip_for_speech(None), "")  # type: ignore[arg-type]

    def test_long_replies_are_cut_and_say_so(self):
        text = "word " * 200
        spoken = speaker().clip_for_speech(text)
        self.assertLess(len(spoken), 160)
